import { __decorate } from "tslib";
import __NG_CLI_RESOURCE__0 from "./SuccessChip.css?ngResource";
import { Component, Input, ViewEncapsulation } from '@angular/core';
import { ChipSelectIconComponent, ChipSelectedIconComponent } from '../Chip/chip-icons.component';
import { IconFrameComponent } from '../Icon/icon-frame.component';
const typeClass = {
    chip: 'orbit-chip--chip',
    tag: 'orbit-chip--tag',
};
const sizeClass = {
    default: 'orbit-chip--default',
    compact: 'orbit-chip--compact',
};
let SuccessChipComponent = class SuccessChipComponent {
    constructor() {
        this.type = 'chip';
        this.size = 'default';
        this.selected = false;
        this.iconSize = 'small';
        this.showIcon = true;
        this.label = 'Text';
        this.disabled = false;
        this.className = '';
    }
    get showLabel() {
        return this.label != null && this.label !== '';
    }
    get classes() {
        return [
            'orbit-chip',
            'orbit-success-chip',
            typeClass[this.type],
            sizeClass[this.size],
            this.selected ? 'orbit-success-chip--selected' : undefined,
            this.className,
        ]
            .filter(Boolean)
            .join(' ');
    }
    static { this.propDecorators = {
        type: [{ type: Input }],
        size: [{ type: Input }],
        selected: [{ type: Input }],
        iconSize: [{ type: Input }],
        showIcon: [{ type: Input }],
        label: [{ type: Input }],
        disabled: [{ type: Input }],
        className: [{ type: Input }]
    }; }
};
SuccessChipComponent = __decorate([
    Component({
        selector: 'orbit-success-chip',
        standalone: true,
        imports: [IconFrameComponent, ChipSelectIconComponent, ChipSelectedIconComponent],
        encapsulation: ViewEncapsulation.None,
        template: `
    <button
      type="button"
      [class]="classes"
      [disabled]="disabled"
      [attr.aria-pressed]="selected"
      [attr.aria-disabled]="disabled || null"
    >
      <span class="orbit-chip__content">
        @if (showIcon) {
          <orbit-icon-frame [size]="iconSize" className="orbit-chip__icon">
            @if (selected) {
              <ng-content select="[orbitSelectedIcon]">
                <orbit-chip-selected-icon></orbit-chip-selected-icon>
              </ng-content>
            } @else {
              <ng-content select="[orbitIcon]">
                <orbit-chip-select-icon></orbit-chip-select-icon>
              </ng-content>
            }
          </orbit-icon-frame>
        }
        @if (showLabel) {
          <span class="orbit-chip__label"><ng-content>{{ label }}</ng-content></span>
        }
      </span>
    </button>
  `,
        styles: [__NG_CLI_RESOURCE__0]
    })
], SuccessChipComponent);
export { SuccessChipComponent };
